begin;
create or replace function public.open_school_invitation(p_token text) returns text language plpgsql security definer set search_path=pg_catalog as $$ declare current_status public.school_invitation_status; begin select status into current_status from public.school_invitations where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and expires_at>now() for update; if current_status is null then return 'unavailable'; end if; update public.school_invitations set status=case when status='sent' then 'opened' else status end,opened_at=coalesce(opened_at,now()) where token_hash=encode(extensions.digest(p_token,'sha256'),'hex'); return 'opened'; end $$;
create or replace function public.claim_school_invitation(p_token text) returns text language plpgsql security definer set search_path=pg_catalog as $$ declare invitation public.school_invitations%rowtype; existing_status public.school_membership_status; begin if auth.uid() is null or not public.is_verified_email_user() then raise exception 'verified email required' using errcode='42501'; end if; if not public.has_current_onboarding_consents(auth.uid()) then raise exception 'current Terms, Privacy and Community Safety consent required' using errcode='42501'; end if; select * into invitation from public.school_invitations where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and expires_at>now() for update; if invitation.id is null or invitation.status in ('expired','revoked') then raise exception 'invitation unavailable' using errcode='P0002'; end if; if invitation.status in ('joined','approved') then if invitation.joined_by=auth.uid() then return case when invitation.status='approved' then 'already_approved' else 'pending' end; end if; raise exception 'invitation unavailable' using errcode='P0002'; end if; select status into existing_status from public.school_memberships where school_id=invitation.school_id and user_id=auth.uid() for update; if existing_status='verified' then return 'already_verified'; end if; if existing_status='suspended' then raise exception 'membership is suspended' using errcode='42501'; end if; insert into public.school_memberships(school_id,user_id,status,verified_email_at,invite_code_verified_at) values(invitation.school_id,auth.uid(),'pending',now(),now()) on conflict(school_id,user_id) do update set status='pending',verified_email_at=now(),invite_code_verified_at=now(),updated_at=now(); update public.school_invitations set status='joined',joined_at=now(),joined_by=auth.uid() where id=invitation.id; insert into public.analytics_events(actor_id,school_id,event_name) values(auth.uid(),invitation.school_id,'invite_joined'); insert into public.audit_logs(actor_id,school_id,action,entity_type,entity_id,payload) values(auth.uid(),invitation.school_id,'invitation.joined','school_invitation',invitation.id,jsonb_build_object('outcome','joined')); return 'pending'; end $$;
create or replace function public.redeem_school_invite_code(p_school_id uuid,p_code text) returns text language plpgsql security definer set search_path=pg_catalog as $$ declare matching_code_id uuid; existing_status public.school_membership_status; begin if auth.uid() is null or not public.is_verified_email_user() then raise exception 'verified email required' using errcode='42501'; end if; if not public.has_current_onboarding_consents(auth.uid()) then raise exception 'current Terms, Privacy and Community Safety consent required' using errcode='42501'; end if; if char_length(trim(p_code))<6 or char_length(trim(p_code))>128 then raise exception 'invalid invite code' using errcode='22023'; end if; perform pg_advisory_xact_lock(hashtext(auth.uid()::text)); select status into existing_status from public.school_memberships where school_id=p_school_id and user_id=auth.uid() for update; if existing_status='verified' then return 'already_verified'; end if; if existing_status='suspended' then raise exception 'membership is suspended' using errcode='42501'; end if; if (select count(*) from public.school_invite_attempts where user_id=auth.uid() and attempted_at>now()-interval '15 minutes')>=5 then raise exception 'invite attempts rate limited' using errcode='P0001'; end if; insert into public.school_invite_attempts(user_id) values(auth.uid()); select code.id into matching_code_id from public.school_invite_codes code where code.school_id=p_school_id and code.is_active and code.expires_at>now() and code.use_count<code.max_uses and extensions.crypt(trim(p_code),code.code_hash)=code.code_hash for update; if matching_code_id is null then raise exception 'invalid invite code' using errcode='22023'; end if; update public.school_invite_codes set use_count=use_count+1 where id=matching_code_id; insert into public.school_memberships(school_id,user_id,status,verified_email_at,invite_code_verified_at) values(p_school_id,auth.uid(),'pending',now(),now()) on conflict(school_id,user_id) do update set status='pending',verified_email_at=now(),invite_code_verified_at=now(),updated_at=now(); insert into public.analytics_events(actor_id,school_id,event_name) values(auth.uid(),p_school_id,'school_joined'); insert into public.audit_logs(actor_id,school_id,action,entity_type,payload) values(auth.uid(),p_school_id,'membership.invite_code_redeemed','school_membership',jsonb_build_object('source','invite_code','outcome','pending')); return 'pending'; end $$;
create or replace function public.claim_household_link_invitation(p_token text) returns uuid language plpgsql security definer set search_path=pg_catalog as $$ declare invitation public.household_link_invitations%rowtype; existing_link public.household_links%rowtype; link_id uuid; begin if auth.uid() is null or char_length(trim(p_token))<>48 then raise exception 'household confirmation code is unavailable' using errcode='P0002'; end if; select * into invitation from public.household_link_invitations where token_hash=encode(extensions.digest(trim(p_token),'sha256'),'hex') and expires_at>now() for update; if invitation.id is null or invitation.claimed_by is not null or invitation.invited_by=auth.uid() or not public.is_member(invitation.school_id) then raise exception 'household confirmation code is unavailable' using errcode='P0002'; end if; if not exists(select 1 from public.school_memberships m where m.school_id=invitation.school_id and m.user_id=auth.uid() and m.status='verified') then raise exception 'household confirmation code is unavailable' using errcode='P0002'; end if; select * into existing_link from public.household_links l where l.school_id=invitation.school_id and l.status in ('pending','confirmed') and least(l.first_parent_id,l.second_parent_id)=least(invitation.invited_by,auth.uid()) and greatest(l.first_parent_id,l.second_parent_id)=greatest(invitation.invited_by,auth.uid()) for update; if existing_link.id is null then insert into public.household_links(school_id,first_parent_id,second_parent_id,requested_by,requester_confirmed_at,other_parent_confirmed_at,status) values(invitation.school_id,least(invitation.invited_by,auth.uid()),greatest(invitation.invited_by,auth.uid()),invitation.invited_by,now(),now(),'confirmed') returning id into link_id; elsif existing_link.status='confirmed' then link_id:=existing_link.id; elsif existing_link.requested_by=invitation.invited_by then update public.household_links set status='confirmed',other_parent_confirmed_at=now(),updated_at=now() where id=existing_link.id; link_id:=existing_link.id; else raise exception 'household confirmation code is unavailable' using errcode='P0002'; end if; update public.household_link_invitations set claimed_by=auth.uid(),claimed_at=now() where id=invitation.id; insert into public.audit_logs(actor_id,school_id,action,entity_type,entity_id,payload) values(auth.uid(),invitation.school_id,'household.invitation_claimed','household_link',link_id,jsonb_build_object('outcome','confirmed')); return link_id; end $$;
commit;
